input.command:
for url in kenshoen okyaku mukumi ashi hiza hizi; do
  echo "=== $url ===";
  curl -s "https://td-group.test-page.site/symptoms/$url/" -o "/private/tmp/claude-501/-Users-rina--claude/cefe6fd7-bdc7-4cfd-aff5-3b63ac26f1c4/scratchpad/$url.html";
  echo "saved, size: $(wc -c < "/private/tmp/claude-501/-Users-rina--claude/cefe6fd7-bdc7-4cfd-aff5-3b63ac26f1c4/scratchpad/$url.html")";
done

SCRATCH="/private/tmp/claude-501/-Users-rina--claude/cefe6fd7-bdc7-4cfd-aff5-3b63ac26f1c4/scratchpad"
for url in kenshoen okyaku mukumi ashi hiza hizi; do
  echo "===== $url =====";
  echo "--- TITLE ---";
  grep -o '<title>[^<]*</title>' "$SCRATCH/$url.html";
  echo "--- META DESCRIPTION ---";
  grep -o '<meta name="description"[^>]*>' "$SCRATCH/$url.html";
  echo "--- H1 ---";
  grep -o '<h1[^>]*>.*</h1>' "$SCRATCH/$url.html" | head -5;
  echo "";
done
